using System.Security.Cryptography;using System.Text;
namespace Hs.LangSense;
public sealed record ValueDiff(bool Same,ComparisonMode Mode,string Left,string Right,string Reason);
public static class Canonicalizer { public static string Create(string? value,ComparisonMode mode=ComparisonMode.Semantic){var s=Normalizer.Normalize(value);return mode switch {ComparisonMode.Exact=>value??"",ComparisonMode.Normalized=>s,ComparisonMode.Canonical=>s.ToLowerInvariant(),ComparisonMode.Search=>SearchNormalizer.Normalize(s),_=>Semantic(s)};} private static string Semantic(string s){s=s.ToLowerInvariant();s=s.Replace("ي","ی").Replace("ى","ی").Replace("ك","ک");s=new string(s.Where(c=>!char.IsWhiteSpace(c)&&c!='-'&&c!='_'&&c!=',').ToArray());return s;}}
public static class ValueComparer { public static bool Equals(string? a,string? b,ComparisonMode mode=ComparisonMode.Semantic)=>Canonicalizer.Create(a,mode)==Canonicalizer.Create(b,mode);public static ValueDiff Compare(string? a,string? b,ComparisonMode mode=ComparisonMode.Semantic){var x=Canonicalizer.Create(a,mode);var y=Canonicalizer.Create(b,mode);return new(x==y,mode,x,y,x==y?"Equivalent under selected mode":"Different under selected mode");}}
public static class SearchNormalizer { public static string Normalize(string? s){var x=Normalizer.Normalize(s).Replace('ي','ی').Replace('ى','ی').Replace('ك','ک').ToLowerInvariant();return new string(x.Where(c=>!char.IsWhiteSpace(c)).ToArray());} }
internal static class CanonicalizerHelpers { }
public static class SemanticFingerprint { public static string Create(string? value,ComparisonMode mode=ComparisonMode.Semantic){using var sha=SHA256.Create();var bytes=Encoding.UTF8.GetBytes(Canonicalizer.Create(value,mode));return Convert.ToHexString(sha.ComputeHash(bytes)).ToLowerInvariant();} }
public static class SmartDiff { public static ValueDiff Compare(string a,string b){if(a==b)return new(true,ComparisonMode.Exact,a,b,"Exact match");if(Canonicalizer.Create(a,ComparisonMode.Semantic)==Canonicalizer.Create(b,ComparisonMode.Semantic))return new(true,ComparisonMode.Semantic,a,b,"Formatting/representation changed; semantic value unchanged");if(Canonicalizer.Create(a,ComparisonMode.Normalized)==Canonicalizer.Create(b,ComparisonMode.Normalized))return new(true,ComparisonMode.Normalized,a,b,"Normalization changed only");return new(false,ComparisonMode.Semantic,a,b,"Semantic value changed");} }
